 const vault=new AesCredentialVault(new Uint8Array(32).fill(7)),policy={allowedHosts:[],allowLoopback:true};
 const validProvider:InvestigationProvider={analyze:async input=>({output:{summary:'بررسی فنی',insufficientEvidence:false,hypotheses:[{explanation:'فرضیه برای بررسی انسانی',confidence:.5,evidence:[JSON.parse(input.evidence)[0].reference]}],recommendedActions:[]},inputTokens:20,outputTokens:10})};
