    const role=`jupiter_app_${name}`;
    await admin.query(`CREATE DATABASE "${name}"`);
    const cfg=connectionString?(()=>{const url=new URL(connectionString);url.pathname=`/${name}`;return{connectionString:url.toString()};})():{...connection,database:name};
    const client=new Client(cfg);
